import boto3

def embed_secret_audit_notes(notes):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        model_id='amazon.titan-embed-text-v1',
        body={
            'inputText': notes
        }
    )
    result = json.loads(response['body'].read())
    return result['embedding']

if __name__ == '__main__'):
    audit_notes = 'Example secret audit notes'
    embedding = embed_secret_audit_notes(audit_notes)
    print(embedding)

import boto3

def check_unsafe_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    return False

def main():
    secret_labels = ['label1', 'label2']
    secret_notes = ['note1', 'note2']
    for label in secret_labels:
        if check_unsafe_text(label):
            print(f'Unsafe text detected in label: {label}')
    for note in secret_notes:
        if check_unsafe_text(note):
            print(f'Unsafe text detected in note: {note}')

if __name__ == '__main__':
    main()

from typing import Dict, Any

import boto3

client = boto3.client('secretsmanager')

def get_secret(secret_name: str) -> Dict[str, Any]:
    response = client.get_secret_value(SecretId=secret_name)
    return json.loads(response['SecretString'])

def put_secret(secret_name: str, secret_value: Dict[str, Any]) -> None:
    client.put_secret_value(SecretId=secret_name, SecretString=json.dumps(secret_value))

def normalize_secret(secret: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in secret.items() if k!= 'AWSCURRENT'}
